import React, { useEffect, useState, useMemo } from "react";
import AxiosInstance from "../../../AxiosInstance";
import * as XLSX from "xlsx";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import {
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  BarChart,
  Bar,
  LineChart,
  Line,
  ResponsiveContainer,
} from "recharts";
import LoadingSpinner from "../../LoadingSpinner";

interface AttendanceLog {
  id: number;
  date: string;
  type: string;
  fullname: string;
  address?: string;
  contact_number?: string;
  purpose: string;
  affiliation: string;
  time_in: string;
  time_out?: string;
}

// This allows TS to recognize the 'lastAutoTable' property added by the plugin
interface jsPDFWithPlugin extends jsPDF {
  lastAutoTable: {
    finalY: number;
  };
}

interface AttendanceTabProps {
  activeTab: string;
}

const AttendanceTab: React.FC<AttendanceTabProps> = ({ activeTab }) => {
  // ===== STATES =====
  const [loadingAttendance, setLoadingAttendance] = useState(false);
  const [attendanceSort, setAttendanceSort] = useState<"asc" | "desc">("desc");
  const [currentPageAttendance, setCurrentPageAttendance] = useState(1);
  const rowsPerPageAttendance = 10;

  const [attendanceSummaryData, setAttendanceSummaryData] = useState<any[]>([]);
  const [attendanceLogData, setAttendanceLogData] = useState<any[]>([]);

  const [dateFilter, setDateFilter] = useState("today");

  // ===== FETCH DATA =====
  useEffect(() => {
    if (activeTab === "attendance") {
      const fetchAttendanceReports = async () => {
        setLoadingAttendance(true);
        try {
          const [summaryRes, logRes] = await Promise.all([
            AxiosInstance.get("/reports/attendance/summary"),
            AxiosInstance.get("/reports/attendance/log"),
          ]);

          setAttendanceSummaryData(summaryRes.data.rows || []);
          setAttendanceLogData(logRes.data.logs || []);
        } catch (error) {
          console.error("Error fetching attendance reports:", error);
        } finally {
          setLoadingAttendance(false);
        }
      };
      fetchAttendanceReports();
    }
  }, [activeTab]);

  // ===== LOGIC: SORTING & PAGINATION =====
  const sortedLogs = useMemo(() => {
    return [...attendanceLogData].sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return attendanceSort === "asc" ? dateA - dateB : dateB - dateA;
    });
  }, [attendanceLogData, attendanceSort]);

  const totalPagesAttendance = Math.ceil(
    sortedLogs.length / rowsPerPageAttendance
  );
  const indexOfLastAttendance = currentPageAttendance * rowsPerPageAttendance;
  const indexOfFirstAttendance = indexOfLastAttendance - rowsPerPageAttendance;
  const currentAttendance = sortedLogs.slice(
    indexOfFirstAttendance,
    indexOfLastAttendance
  );

  // ===== LOGIC: DATE FILTERING =====
  const filteredAttendance = useMemo(() => {
    const now = new Date();
    // Changed attendanceData -> attendanceLogData
    return attendanceLogData.filter((entry) => {
      // Changed entry.date_added -> entry.date (to match your API structure)
      const entryDate = new Date(entry.date);

      if (dateFilter === "today") {
        return entryDate.toDateString() === now.toDateString();
      }
      if (dateFilter === "week") {
        const startOfWeek = new Date();
        startOfWeek.setDate(now.getDate() - now.getDay());
        startOfWeek.setHours(0, 0, 0, 0); // Reset time for accurate comparison
        return entryDate >= startOfWeek;
      }
      if (dateFilter === "month") {
        return (
          entryDate.getMonth() === now.getMonth() &&
          entryDate.getFullYear() === now.getFullYear()
        );
      }
      if (dateFilter === "year") {
        return entryDate.getFullYear() === now.getFullYear();
      }
      return true; // "all"
    });
  }, [dateFilter, attendanceLogData]); // Dependencies updated

  // ===== EXPORT TO EXCEL =====
  const exportAttendanceLogToExcel = () => {
    if (!attendanceLogData.length) return;

    const data = attendanceLogData.map((row) => ({
      Date: row.date,
      Type: row.type?.toUpperCase(),
      "Full Name": row.fullname,
      Address: row.address,
      "Contact Number": row.contact_number,
      Purpose: row.purpose,
      Affiliation: row.affiliation,
      "Time In": row.time_in,
      "Time Out": row.time_out,
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Attendance Log");
    XLSX.writeFile(workbook, "attendance_log.xlsx");
  };

  const LIBRARY_LOGO_BASE64 =
    "data:image/jpeg;base64,";

  // ===== EXPORT TO PDF =====
  const exportAttendanceToPDF = (dataToPrint: AttendanceLog[]) => {
    // Cast doc to our extended interface
    const doc = new jsPDF() as jsPDFWithPlugin;
    const today = new Date().toLocaleDateString();

    try {
      // x=95 (center-ish), y=10, width=20, height=20
      doc.addImage(LIBRARY_LOGO_BASE64, "PNG", 95, 10, 20, 20);
    } catch (e) {
      console.error("Logo failed to load", e);
    }

    doc.setFontSize(18);
    doc.setTextColor(31, 78, 121);
    doc.setFont("helvetica", "bold");
    doc.text("CAPIZ PROVINCIAL LIBRARY", 105, 40, { align: "center" });

    doc.setFontSize(12);
    doc.setTextColor(100);
    doc.setFont("helvetica", "normal");
    doc.text("Capiz E-Lib System", 105, 47, { align: "center" });

    // 2. Report Title
    doc.setFontSize(14);
    doc.setTextColor(0);
    doc.text("ATTENDANCE REPORT", 14, 60);

    doc.setFontSize(10);
    doc.text(
      `Generated on: ${today} | Scope: ${dateFilter.toUpperCase()}`,
      14,
      67
    );

    // 3. Table
    const tableRows = dataToPrint.map((row: AttendanceLog) => [
      row.date,
      row.type?.toUpperCase() || "N/A",
      row.fullname,
      row.purpose,
      row.affiliation,
      `In: ${row.time_in}\nOut: ${row.time_out || "--:--"}`,
    ]);

    autoTable(doc, {
      startY: 75, // Pushed down to make room for logo + title
      head: [["Date", "Type", "Full Name", "Purpose", "Affiliation", "In/Out"]],
      body: tableRows,
      theme: "grid",
      headStyles: {
        fillColor: [173, 216, 230],
        textColor: [0, 0, 0],
        fontStyle: "bold",
      },
      styles: { fontSize: 8, halign: "center" },
      columnStyles: { 2: { halign: "left", fontStyle: "bold" } },
    });

    // 5. Footer Section (Dynamically positioned)
    const finalY = doc.lastAutoTable.finalY + 20;

    // Check if signature will overflow page; if so, add new page
    const pageHeight = doc.internal.pageSize.height;
    if (finalY + 50 > pageHeight) {
      doc.addPage();
      doc.setPage(doc.getNumberOfPages());
    }

    doc.setFontSize(10);
    doc.setTextColor(0);
    doc.text("Approved By:", 14, finalY);

    doc.text("______________________________", 14, finalY + 15);
    doc.text("Library Administrator / Librarian-in-Charge", 14, finalY + 20);
    doc.text(`Date Printed: ${today}`, 14, finalY + 30);

    doc.setFontSize(9);
    doc.setTextColor(150);
    doc.text("Official System-Generated Report", 105, pageHeight - 10, {
      align: "center",
    });

    doc.save(`Attendance_Report_${dateFilter}_${today}.pdf`);
  };

  if (loadingAttendance) return <LoadingSpinner />;

  return (
    <div className="attendance-section animate-fade-in">
      {/* ===== Row 1: Charts + Summary Table ===== */}
      <div className="attendance-top d-flex flex-wrap gap-4 mb-4">
        {/* Left: Charts (66% width on large screens) */}
        <div
          className="attendance-charts flex-grow-1"
          style={{ flexBasis: "60%" }}
        >
          <div className="row g-3">
            {/* Bar Chart */}
            <div className="col-12 col-xl-6">
              <div className="card shadow-sm p-3">
                <div className="chart-header d-flex justify-content-between mb-3">
                  <h6 className="fw-bold">Patron vs Guest</h6>
                  <span className="badge bg-primary-subtle text-primary">
                    Weekly
                  </span>
                </div>
                <ResponsiveContainer width="100%" height={250}>
                  <BarChart data={attendanceSummaryData}>
                    <CartesianGrid
                      strokeDasharray="3 3"
                      vertical={false}
                      stroke="#eee"
                    />
                    <XAxis
                      dataKey="date"
                      fontSize={11}
                      tickLine={false}
                      axisLine={false}
                    />
                    <YAxis fontSize={11} tickLine={false} axisLine={false} />
                    <Tooltip
                      cursor={{ fill: "#f5f5f5" }}
                      contentStyle={{ borderRadius: "8px", border: "none" }}
                    />
                    <Legend
                      iconType="circle"
                      wrapperStyle={{ fontSize: "12px" }}
                    />
                    <Bar
                      dataKey="guest"
                      name="Guest"
                      fill="#8884d8"
                      radius={[4, 4, 0, 0]}
                      barSize={20}
                    />
                    <Bar
                      dataKey="patron"
                      name="Patron"
                      fill="#82ca9d"
                      radius={[4, 4, 0, 0]}
                      barSize={20}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Line Chart */}
            <div className="col-12 col-xl-6">
              <div className="card shadow-sm p-3">
                <div className="chart-header d-flex justify-content-between mb-3">
                  <h6 className="fw-bold">Visitor Volume</h6>
                  <span className="badge bg-warning-subtle text-warning">
                    Trend
                  </span>
                </div>
                <ResponsiveContainer width="100%" height={250}>
                  <LineChart data={attendanceSummaryData}>
                    <CartesianGrid
                      strokeDasharray="3 3"
                      vertical={false}
                      stroke="#eee"
                    />
                    <XAxis
                      dataKey="date"
                      fontSize={11}
                      tickLine={false}
                      axisLine={false}
                    />
                    <YAxis fontSize={11} tickLine={false} axisLine={false} />
                    <Tooltip
                      contentStyle={{ borderRadius: "8px", border: "none" }}
                    />
                    <Legend
                      iconType="circle"
                      wrapperStyle={{ fontSize: "12px" }}
                    />
                    <Line
                      type="monotone"
                      dataKey="total"
                      name="Total Visitors"
                      stroke="#ff7300"
                      strokeWidth={3}
                      dot={{ r: 4 }}
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>

        {/* Right: Modern Summary Table */}
        <div
          className="attendance-summary card"
          style={{
            minWidth: "320px",
            height: "327px",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <div
            className="card-body p-4 d-flex flex-column"
            style={{ height: "100%" }}
          >
            <div className="d-flex justify-content-between align-items-center mb-4 flex-shrink-0">
              <h6 className="fw-bold mb-0 text-dark">Recent Activity</h6>
            </div>

            <div
              className="summary-list"
              style={{ maxHeight: "300px", overflowY: "auto" }}
            >
              {attendanceSummaryData.map((row, i) => {
                const total = row.total || 1; // Prevent division by zero
                const patronPercent = (row.patron / total) * 100;

                return (
                  <div
                    key={i}
                    className="summary-item mb-4 pb-3 border-bottom border-light"
                  >
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <div>
                        <span className="fw-bold d-block">{row.date}</span>
                        <small className="text-muted">
                          {row.total} Total Visitors
                        </small>
                      </div>
                      <div className="text-end">
                        <span className="badge rounded-pill bg-dark px-3">
                          {row.total}
                        </span>
                      </div>
                    </div>

                    {/* Visual breakdown bar */}
                    <div
                      className="progress"
                      style={{ height: "6px", backgroundColor: "#f0f0f0" }}
                    >
                      <div
                        className="progress-bar"
                        role="progressbar"
                        style={{
                          width: `${100 - patronPercent}%`,
                          backgroundColor: "#8884d8",
                        }}
                        aria-label="Guests"
                      />
                      <div
                        className="progress-bar"
                        role="progressbar"
                        style={{
                          width: `${patronPercent}%`,
                          backgroundColor: "#82ca9d",
                        }}
                        aria-label="Patrons"
                      />
                    </div>

                    <div
                      className="d-flex justify-content-between mt-2"
                      style={{ fontSize: "0.75rem" }}
                    >
                      <span className="text-muted">
                        <i
                          className="bi bi-circle-fill me-1"
                          style={{ color: "#8884d8", fontSize: "8px" }}
                        ></i>
                        Guest: <strong>{row.guest}</strong>
                      </span>
                      <span className="text-muted">
                        <i
                          className="bi bi-circle-fill me-1"
                          style={{ color: "#82ca9d", fontSize: "8px" }}
                        ></i>
                        Patron: <strong>{row.patron}</strong>
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      {/* ===== Row 2: Detailed Attendance Log ===== */}
      <div className="attendance-log-section card shadow-sm">
        <div className="card-header bg-white py-3 d-flex justify-content-between align-items-center">
          <div>
            <h5 className="mb-0">Attendance Log</h5>
            <small className="text-muted">Detailed list of all visitors</small>
          </div>
          <div className="d-flex gap-2">
            <div className="btn-group btn-group-sm">
              <button
                className={`btn btn-outline-secondary ${
                  attendanceSort === "asc" ? "active" : ""
                }`}
                onClick={() => setAttendanceSort("asc")}
              >
                Oldest
              </button>
              <button
                className={`btn btn-outline-secondary ${
                  attendanceSort === "desc" ? "active" : ""
                }`}
                onClick={() => setAttendanceSort("desc")}
              >
                Newest
              </button>
            </div>
            <div className="d-flex gap-2 align-items-center">
              <select
                className="form-select form-select-sm shadow-none"
                style={{
                  width: "160px",
                  borderRadius: "6px",
                  borderColor: "#e0e0e0",
                }}
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value)}
              >
                <option value="today">Today's Attendance</option>
                <option value="week">This Week</option>
                <option value="month">This Month</option>
                <option value="year">This Year</option>
                <option value="all">All Records</option>
              </select>

              <button
                onClick={() => exportAttendanceToPDF(filteredAttendance)}
                className="btn btn-sm btn-danger px-3 shadow-sm"
                style={{
                  borderRadius: "6px",
                  backgroundColor: "#EF4444",
                  border: "none",
                }}
              >
                <i className="bi bi-file-pdf me-2"></i>
                Print PDF ({filteredAttendance.length})
              </button>
              <button
                onClick={exportAttendanceLogToExcel}
                className="btn btn-sm btn-success"
              >
                <i className="bi bi-file-earmark-spreadsheet me-1"></i> Export
                Excel
              </button>
            </div>
          </div>
        </div>

        <div className="table-responsive">
          <table
            className="table table-hover align-middle mb-0"
            style={{ fontSize: "0.9rem" }}
          >
            <thead className="table-light">
              <tr>
                <th>Date</th>
                <th>Type</th>
                <th>Full Name</th>
                <th>Purpose</th>
                <th>Affiliation</th>
                <th>In/Out</th>
              </tr>
            </thead>
            <tbody>
              {currentAttendance.map((row) => (
                <tr key={row.id}>
                  <td>{row.date}</td>
                  <td>
                    <span
                      className={`badge ${
                        row.type === "patron"
                          ? "bg-info-subtle text-info"
                          : "bg-secondary-subtle text-secondary"
                      } text-capitalize`}
                    >
                      {row.type}
                    </span>
                  </td>
                  <td className="fw-medium">{row.fullname}</td>
                  <td className="text-truncate" style={{ maxWidth: "150px" }}>
                    {row.purpose}
                  </td>
                  <td>{row.affiliation}</td>
                  <td>
                    <div className="small">
                      <span className="text-success">In: {row.time_in}</span>
                      <br />
                      <span className="text-muted">
                        Out: {row.time_out || "--:--"}
                      </span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination Footer */}
        <div className="card-footer bg-white d-flex justify-content-between align-items-center py-3">
          <span className="small text-muted">
            Showing {indexOfFirstAttendance + 1} to{" "}
            {Math.min(indexOfLastAttendance, sortedLogs.length)} of{" "}
            {sortedLogs.length} entries
          </span>
          <nav>
            <ul className="pagination pagination-sm mb-0 gap-1">
              <li
                className={`page-item ${
                  currentPageAttendance === 1 ? "disabled" : ""
                }`}
              >
                <button
                  className="page-link rounded border-0 bg-light text-muted"
                  onClick={() => setCurrentPageAttendance((p) => p - 1)}
                >
                  Previous
                </button>
              </li>
              {[...Array(totalPagesAttendance)].map((_, i) => (
                <li
                  key={i}
                  className={`page-item ${
                    currentPageAttendance === i + 1 ? "active" : ""
                  }`}
                >
                  <button
                    className="page-link rounded border-0 mx-1 shadow-none"
                    onClick={() => setCurrentPageAttendance(i + 1)}
                    style={{
                      backgroundColor:
                        currentPageAttendance === i + 1
                          ? "#c05b42"
                          : "transparent",
                      color:
                        currentPageAttendance === i + 1 ? "#fff" : "#64748b",
                      fontWeight:
                        currentPageAttendance === i + 1 ? "600" : "400",
                    }}
                  >
                    {i + 1}
                  </button>
                </li>
              ))}
              <li
                className={`page-item ${
                  currentPageAttendance === totalPagesAttendance
                    ? "disabled"
                    : ""
                }`}
              >
                <button
                  className="page-link rounded border-0 bg-light text-muted"
                  onClick={() => setCurrentPageAttendance((p) => p + 1)}
                >
                  Next
                </button>
              </li>
            </ul>
          </nav>
        </div>
      </div>
    </div>
  );
};

export default AttendanceTab;
